{"source":{"files":[{"name":"firestore.rules","content":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /hd0000/{room} {
      allow read: if resource.data.n is int;
    }
    match /hd0001/{room} {
      allow read: if resource.data.f is float;
    }
    match /hd0002/{room} {
      allow read: if resource.data.n is float;
    }
    match /hd0003/{room} {
      allow read: if resource.data.n is number;
    }
    match /hd0004/{room} {
      allow read: if resource.data.f is number;
    }
    match /hd0005/{room} {
      allow read: if resource.data.s is string;
    }
    match /hd0006/{room} {
      allow read: if resource.data.b is bool;
    }
    match /hd0007/{room} {
      allow read: if resource.data.arr is list;
    }
    match /hd0008/{room} {
      allow read: if resource.data.m is map;
    }
    match /hd0009/{room} {
      allow read: if resource.data.ts is timestamp;
    }
    match /hd0010/{room} {
      allow read: if resource.data.geo is latlng;
    }
    match /hd0011/{room} {
      allow read: if resource.data.ref is path;
    }
    match /hd0012/{room} {
      allow read: if resource.data.by is bytes;
    }
    match /hd0013/{room} {
      allow read: if resource.data.missing is string;
    }
    match /hd0014/{room} {
      allow read: if !(resource.data.s is int);
    }
    match /hd0015/{room} {
      allow read: if duration.value(1, 's') is duration;
    }
    match /hd0016/{room} {
      allow read: if [1].toSet() is set;
    }
    match /hd0017/{room} {
      allow read: if resource.data.missing == null;
    }
    match /hd0018/{room} {
      allow read: if resource.data.missing == 1 || true;
    }
    match /hd0019/{room} {
      allow read: if true || resource.data.missing == 1;
    }
    match /hd0020/{room} {
      allow read: if resource.data.missing == 1 && false;
    }
    match /hd0021/{room} {
      allow read: if false && resource.data.missing == 1;
    }
    match /hd0022/{room} {
      allow read: if resource.data.missing == 1 || false;
    }
    match /hd0023/{room} {
      allow read: if !(resource.data.missing == 1);
    }
    match /hd0024/{room} {
      allow read: if resource.data.missing ? true : true;
    }
    match /hd0025/{room} {
      allow read: if resource.data.n == 1 ? true : resource.data.missing;
    }
    match /hd0026/{room} {
      allow read: if resource.data.nul == null;
    }
    match /hd0027/{room} {
      allow read: if resource.data.nul.x == 1;
    }
    match /hd0028/{room} {
      allow read: if resource.data.arr[5] == 1;
    }
    match /hd0029/{room} {
      allow read: if resource.data.arr[5] == 1 || true;
    }
    match /hd0030/{room} {
      allow read: if [resource.data.missing, 1].size() == 2;
    }
    match /hd0031/{room} {
      allow read: if resource.data.missing in [1];
    }
    match /hd0032/{room} {
      allow read: if request.auth == null;
    }
    match /hd0033/{room} {
      allow read: if request.auth.uid == 'x';
    }
    match /hd0034/{room} {
      allow read: if request.auth != null && request.auth.uid == 'x';
    }
    match /hd0035/{room} {
      allow read: if request.resource == null;
    }
    match /hd0036/{room} {
      allow read: if request.method == 'get';
    }
    match /hd0037/{room} {
      allow read: if resource.data.s + 1 == 'abc1';
    }
    match /hd0038/{room} {
      allow read: if (resource.data.s + 1 == 'abc1') || true;
    }
    match /hd0039/{room} {
      allow read: if 'n' in resource.data;
    }
    match /hd0040/{room} {
      allow read: if 'missing' in resource.data;
    }
    match /hd0041/{room} {
      allow read: if resource.data.size() == 14;
    }
    match /hd0042/{room} {
      allow read: if resource.data.m.x == 1;
    }
    match /hd0043/{room} {
      allow read: if resource.data.m['y'] == 'z';
    }
    match /hd0044/{room} {
      allow read: if resource.data.get('missing', 0) == 0;
    }
    match /hd0045/{room} {
      allow read: if resource.data.get('n', 0) == 1;
    }
    match /hd0046/{room} {
      allow read: if resource.data.get(['m', 'x'], 0) == 1;
    }
    match /hd0047/{room} {
      allow read: if resource.data.get(['m', 'w'], 7) == 7;
    }
    match /hd0048/{room} {
      allow read: if resource.data.keys().hasAll(['n', 's']);
    }
    match /hd0049/{room} {
      allow read: if resource.data.keys().hasAny(['zz', 's']);
    }
    match /hd0050/{room} {
      allow read: if resource.data.keys().hasOnly(['n']);
    }
    match /hd0051/{room} {
      allow read: if resource.data.m.values().hasAll([1, 'z']);
    }
    match /hd0052/{room} {
      allow read: if resource.data.m == {'x': 1, 'y': 'z'};
    }
    match /hd0053/{room} {
      allow read: if resource.data.m == {'x': 1.0, 'y': 'z'};
    }
    match /hd0054/{room} {
      allow read: if resource.data.m.diff({'x': 1, 'y': 'w'}).affectedKeys() == ['y'].toSet();
    }
    match /hd0055/{room} {
      allow read: if resource.data.m.diff({'x': 1}).addedKeys() == ['y'].toSet();
    }
    match /hd0056/{room} {
      allow read: if resource.data.m.diff({'x': 1, 'q': 2, 'y': 'z'}).removedKeys() == ['q'].toSet();
    }
    match /hd0057/{room} {
      allow read: if resource.data.m.diff({'x': 2, 'y': 'z'}).changedKeys() == ['x'].toSet();
    }
    match /hd0058/{room} {
      allow read: if resource.data.m.diff({'x': 2, 'y': 'z'}).unchangedKeys() == ['y'].toSet();
    }
    match /hd0059/{room} {
      allow read: if resource.data.arr.size() == 3;
    }
  }
}
