{"source":{"files":[{"name":"firestore.rules","content":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /hd0060/{room} {
      allow read: if resource.data.arr == [1, 2, 3];
    }
    match /hd0061/{room} {
      allow read: if resource.data.arr == [1.0, 2, 3];
    }
    match /hd0062/{room} {
      allow read: if resource.data.arr.hasAll([1, 2]);
    }
    match /hd0063/{room} {
      allow read: if resource.data.arr.hasAny([5, 3]);
    }
    match /hd0064/{room} {
      allow read: if resource.data.arr.hasOnly([1, 2, 3, 4]);
    }
    match /hd0065/{room} {
      allow read: if resource.data.arr.concat([4]) == [1, 2, 3, 4];
    }
    match /hd0066/{room} {
      allow read: if resource.data.arr.removeAll([2]) == [1, 3];
    }
    match /hd0067/{room} {
      allow read: if resource.data.tags.join(',') == 'a,b';
    }
    match /hd0068/{room} {
      allow read: if resource.data.arr[1:3] == [2, 3];
    }
    match /hd0069/{room} {
      allow read: if resource.data.arr.toSet() == [3, 2, 1, 1].toSet();
    }
    match /hd0070/{room} {
      allow read: if [1, 2, 2].toSet().size() == 2;
    }
    match /hd0071/{room} {
      allow read: if 2 in [1, 2].toSet();
    }
    match /hd0072/{room} {
      allow read: if resource.data.tags.toSet().difference(['a'].toSet()) == ['b'].toSet();
    }
    match /hd0073/{room} {
      allow read: if [1, 2].toSet().union([3].toSet()) == [1, 2, 3].toSet();
    }
    match /hd0074/{room} {
      allow read: if [1, 2].toSet().intersection([2, 3].toSet()) == [2].toSet();
    }
    match /hd0075/{room} {
      allow read: if [1, 2].toSet().hasOnly([1, 2, 3]);
    }
    match /hd0076/{room} {
      allow read: if 'abc'.matches('b');
    }
    match /hd0077/{room} {
      allow read: if 'abc'.matches('a.c');
    }
    match /hd0078/{room} {
      allow read: if resource.data.s.matches('[a-c]+');
    }
    match /hd0079/{room} {
      allow read: if resource.data.s.size() == 3;
    }
    match /hd0080/{room} {
      allow read: if 'é'.size() == 1;
    }
    match /hd0081/{room} {
      allow read: if resource.data.s.upper() == 'ABC';
    }
    match /hd0082/{room} {
      allow read: if 'ABC'.lower() == 'abc';
    }
    match /hd0083/{room} {
      allow read: if '  x '.trim() == 'x';
    }
    match /hd0084/{room} {
      allow read: if 'a,b'.split(',') == ['a', 'b'];
    }
    match /hd0085/{room} {
      allow read: if 'aaa'.replace('a', 'b') == 'bbb';
    }
    match /hd0086/{room} {
      allow read: if 'abc'[1] == 'b';
    }
    match /hd0087/{room} {
      allow read: if 'abc'[0:2] == 'ab';
    }
    match /hd0088/{room} {
      allow read: if 'é'.toUtf8().size() == 2;
    }
    match /hd0089/{room} {
      allow read: if 'a' + string(1) == 'a1';
    }
    match /hd0090/{room} {
      allow read: if string(1.0) == '1.0';
    }
    match /hd0091/{room} {
      allow read: if string(null) == 'null';
    }
    match /hd0092/{room} {
      allow read: if string(true) == 'true';
    }
    match /hd0093/{room} {
      allow read: if int('12') == 12;
    }
    match /hd0094/{room} {
      allow read: if float('1.5') == 1.5;
    }
    match /hd0095/{room} {
      allow read: if 'a' < 'b';
    }
    match /hd0096/{room} {
      allow read: if 1 == 1.0;
    }
    match /hd0097/{room} {
      allow read: if resource.data.one_f == 1;
    }
    match /hd0098/{room} {
      allow read: if resource.data.n == 1.0;
    }
    match /hd0099/{room} {
      allow read: if 1 < 1.5;
    }
    match /hd0100/{room} {
      allow read: if 1 + 1.5 == 2.5;
    }
    match /hd0101/{room} {
      allow read: if 3 / 2 == 1;
    }
    match /hd0102/{room} {
      allow read: if 3.0 / 2 == 1.5;
    }
    match /hd0103/{room} {
      allow read: if -5 % 3 == -2;
    }
    match /hd0104/{room} {
      allow read: if int(1.9) == 1;
    }
    match /hd0105/{room} {
      allow read: if 1.0 / 0.0 > 0;
    }
    match /hd0106/{room} {
      allow read: if resource.data.big + 1 > 0;
