service cloud.firestore {
  match /databases/{database}/documents {
    match /hd0300/{room} {
      allow read: if (x || true) == (x || true);
    }
    match /hd0301/{room} {
      allow read: if ((1 + 1) == 2) && ((1 + 1) is int);
    }
    match /hd0302/{room} {
      allow read: if (1 + 1) == (1 + 1);
    }
    match /hd0303/{room} {
      allow read: if (f_unknown(17)) == (f_unknown(17));
    }
    match /hd0304/{room} {
      allow read: if ((f_unknown(17) || true) == true) && ((f_unknown(17) || true) is bool);
    }
    match /hd0305/{room} {
      allow read: if (f_unknown(17) || true) == (f_unknown(17) || true);
    }
    match /hd0306/{room} {
      allow read: if ((40 + 2) == 42) && ((40 + 2) is int);
    }
    match /hd0307/{room} {
      allow read: if (40 + 2) == (40 + 2);
    }
    match /hd0308/{room} {
      allow read: if ((42 + (-7)) == 35) && ((42 + (-7)) is int);
    }
    match /hd0309/{room} {
      allow read: if (42 + (-7)) == (42 + (-7));
    }
    match /hd0310/{room} {
      allow read: if ((-4 + (-2)) == -6) && ((-4 + (-2)) is int);
    }
    match /hd0311/{room} {
      allow read: if (-4 + (-2)) == (-4 + (-2));
    }
    match /hd0312/{room} {
      allow read: if ((42 - 12) == 30) && ((42 - 12) is int);
    }
    match /hd0313/{room} {
      allow read: if (42 - 12) == (42 - 12);
    }
    match /hd0314/{room} {
      allow read: if ((42 - (-22)) == 64) && ((42 - (-22)) is int);
    }
    match /hd0315/{room} {
      allow read: if (42 - (-22)) == (42 - (-22));
    }
    match /hd0316/{room} {
      allow read: if ((-42 - (-12)) == -30) && ((-42 - (-12)) is int);
    }
    match /hd0317/{room} {
      allow read: if (-42 - (-12)) == (-42 - (-12));
